#!/usr/bin/env python3
"""
Mock Wazuh manager (HTTPS) — SPIKE #37738 PoC.

Stands in for the manager side (#37732 transport/auth + #37733 tasks) so the
agent client can be exercised end to end. It is deliberately small and reads
like the proposed contract:

  * TLS server (self-signed cert generated by run.sh).
  * AES-CMAC auth middleware: parses the two headers, rebuilds the canonical
    request, verifies the MAC (via the `openssl mac` CLI, so verification is an
    INDEPENDENT implementation from the client's EVP_MAC), checks the 300 s
    timestamp window. Any failure -> 401 (generic).
  * /stateless : parse H/E, check payload agent-id == authenticated id.
  * /stateful  : accept a whole session, return a synchronous result; dedup
                 retries by X-Session-Id via a 10-minute LRU (proves the design).
  * /control   : startup -> handshake JSON; notify -> {state, tasks[]}; response.
  * A --backpressure flag makes the first /stateless answer 503 + Retry-After to
    exercise the client's back-off path.

Not production code; no external deps beyond python3 stdlib + the openssl CLI.
"""
import argparse, json, subprocess, sys, time, http.server, ssl, threading

KEYS = {}            # agent_id -> aes key hex
SESSIONS = {}        # session_id -> (ts, result)   (10-min LRU, tiny)
STATE = {"backpressure_once": False, "slow_stateful": 0}


def cmac_hex(key_hex, msg_bytes):
    """AES-CMAC via the openssl CLI — an independent verifier from the client."""
    p = subprocess.run(
        ["openssl", "mac", "-cipher", "AES-128-CBC", "-macopt", f"hexkey:{key_hex}", "CMAC"],
        input=msg_bytes, capture_output=True)
    return p.stdout.decode().strip().lower()


def canonical(method, target, agent_id, ts, body: bytes) -> bytes:
    head = f"WAZUH-REQUEST\n1\n{method}\n{target}\n{agent_id}\n{ts}\n".encode()
    return head + body


class Handler(http.server.BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def _send(self, code, obj=None, headers=None):
        body = b"" if obj is None else json.dumps(obj).encode()
        self.send_response(code)
        for k, v in (headers or {}).items():
            self.send_header(k, v)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if body:
            self.wfile.write(body)

    def _fail_auth(self, reason):
        # generic 401 to the client; reason only to our stderr (never logged sensitive)
        sys.stderr.write(f"   [mock] auth reject: {reason}\n")
        self._send(401, {"error": "Invalid client authentication", "code": 401})

    def _authenticate(self, body: bytes):
        if self.headers.get("protocol-version") != "1":
            return None, "bad protocol-version"
        auth = self.headers.get("Authorization", "")
        if not auth.startswith("Wazuh "):
            return None, "bad scheme"
        try:
            agent_id, ts, mac = auth[len("Wazuh "):].split(":")
        except ValueError:
            return None, "malformed authorization"
        if agent_id not in KEYS:
            return None, "unknown agent"
        now = int(time.time())
        if not (now - 300 <= int(ts) <= now + 30):
            return None, "timestamp outside window"
        target = self.path
        want = cmac_hex(KEYS[agent_id], canonical(self.command, target, agent_id, ts, body))
        # constant-time-ish compare (PoC)
        if not want or len(want) != len(mac) or not _consteq(want, mac.lower()):
            return None, "MAC mismatch"
        return agent_id, None

    def _read_body(self):
        n = int(self.headers.get("Content-Length", 0))
        return self.rfile.read(n) if n else b""

    def do_POST(self):
        body = self._read_body()
        agent_id, why = self._authenticate(body)
        if agent_id is None:
            return self._fail_auth(why)

        if self.path == "/stateless":
            return self._stateless(agent_id, body)
        if self.path == "/stateful":
            return self._stateful(agent_id, body)
        if self.path == "/control":
            return self._control(agent_id, body)
        self._send(404, {"error": "unknown endpoint", "code": 404})

    # ---- endpoints ----
    def _stateless(self, agent_id, body):
        if STATE["backpressure_once"]:
            STATE["backpressure_once"] = False
            sys.stderr.write("   [mock] returning 503 + Retry-After: 2 (back-pressure demo)\n")
            return self._send(503, {"error": "Service temporarily unavailable", "code": 503},
                              {"Retry-After": "2"})
        text = body.decode("utf-8", "replace")
        lines = text.split("\n")
        if not lines or not lines[0].startswith("H "):
            return self._send(400, {"error": "Invalid event batch", "code": 400})
        try:
            meta = json.loads(lines[0][2:])
            body_id = meta["wazuh"]["agent"]["id"]
        except Exception:
            return self._send(400, {"error": "Invalid event batch", "code": 400})
        if body_id != agent_id:                      # trusted id is the authenticated one
            return self._send(400, {"error": "Invalid event batch", "code": 400})
        events = [l for l in lines[1:] if l.startswith("E ")]
        sys.stderr.write(f"   [mock] /stateless OK: {len(events)} events from {agent_id}\n")
        self._send(200)                              # empty body on success

    def _stateful(self, agent_id, body):
        sid = self.headers.get("X-Session-Id", "?")
        prune()
        if sid in SESSIONS:                          # retry dedup (10-min LRU)
            sys.stderr.write(f"   [mock] /stateful CACHED result for session {sid}\n")
            return self._send(200, SESSIONS[sid][1])
        # "process + wait for indexer" — simulated (optionally slow, to show the
        # client's other endpoints keep flowing while this request is held open)
        if STATE["slow_stateful"] > 0:
            sys.stderr.write(f"   [mock] /stateful holding session {sid} open for "
                             f"{STATE['slow_stateful']}s (simulated indexer wait)\n")
            time.sleep(STATE["slow_stateful"])
        items = max(0, len(body) - 25)
        result = {"status": "success", "sessionId": sid, "itemsProcessed": items}
        SESSIONS[sid] = (time.time(), result)
        sys.stderr.write(f"   [mock] /stateful processed session {sid}: {len(body)} B\n")
        self._send(200, result)

    def _control(self, agent_id, body):
        try:
            msg = json.loads(body.decode())
        except Exception:
            return self._send(400, {"error": "bad control body", "code": 400})
        phase = msg.get("phase")
        if phase == "startup":
            # handshake JSON (the shape parse_handshake_json already reads)
            return self._send(200, {
                "limits": {"eps": 0}, "cluster_name": "mock", "cluster_node": "node01",
                "agent_groups": ["default"], "merged_sum": msg.get("config_checksum", "")})
        if phase == "notify":
            # notify response: state + a couple of pending tasks (A6)
            return self._send(200, {
                "state": {"limits": {"eps": 0}, "cluster": "mock",
                          "groups": ["default"], "merged_sum": msg.get("merged_sum", "")},
                "tasks": [
                    {"task_id": "018f9a-0001", "type": "active_response", "priority": 1,
                     "payload": {"command": "firewall-drop", "args": "srcip 10.0.0.9"},
                     "created": int(time.time())},
                    {"task_id": "018f9a-0002", "type": "agent_reload_config", "priority": 5,
                     "payload": {"command": "reload"}, "created": int(time.time())},
                ],
                "config_update": None,
                "timestamp": int(time.time())})
        if phase == "response":
            sys.stderr.write("   [mock] /control response (task results) received\n")
            return self._send(200)
        self._send(400, {"error": "unknown phase", "code": 400})

    def log_message(self, *a):
        pass  # quiet the default access log; we print our own


def _consteq(a, b):
    r = 0
    for x, y in zip(a, b):
        r |= ord(x) ^ ord(y)
    return r == 0


def prune():
    cutoff = time.time() - 600
    for k in [k for k, (t, _) in SESSIONS.items() if t < cutoff]:
        del SESSIONS[k]


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--port", type=int, default=27840)
    ap.add_argument("--cert", required=True)
    ap.add_argument("--key", required=True)
    ap.add_argument("--keys", required=True, help="client.keys-style: 'id keyhex' per line")
    ap.add_argument("--backpressure", action="store_true", help="answer first /stateless with 503")
    ap.add_argument("--slow-stateful", type=int, default=0, metavar="SECONDS",
                    help="hold each /stateful request open this long (concurrency demo)")
    args = ap.parse_args()

    for line in open(args.keys):
        line = line.strip()
        if line and not line.startswith("#"):
            aid, khex = line.split()[:2]
            KEYS[aid] = khex
    STATE["backpressure_once"] = args.backpressure
    STATE["slow_stateful"] = args.slow_stateful

    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
    ctx.load_cert_chain(args.cert, args.key)
    httpd = http.server.ThreadingHTTPServer(("127.0.0.1", args.port), Handler)
    httpd.socket = ctx.wrap_socket(httpd.socket, server_side=True)
    sys.stderr.write(f"   [mock] HTTPS manager on https://127.0.0.1:{args.port} "
                     f"(agents: {list(KEYS)}, backpressure={args.backpressure})\n")
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass


if __name__ == "__main__":
    main()
